lifecycle = r'''async function applyCloud(options={}){if(!st.cloud?.save_data||!appReady())return false;st.apply=true;try{const ok=window.POWDER_APP.applyCloudBundle(st.cloud.save_data,{revision:st.revision});if(ok!==true)throw new Error('Cloud Save không hợp lệ hoặc không thể áp dụng.');const modal=$('#onlineConflictModal');if(modal)modal.hidden=true;status('online');if(!options?.silent)toast('Đã tải tiến độ Cloud về máy.');return true}catch(e){console.error('[Cloud canonical apply]',e);status('error');if(!options?.silent)toast(e.message);return false}finally{st.apply=false}}
async function recoverUseCloud(){return applyCloud({silent:false})}
async function recoverUseLocal(){const modal=$('#onlineConflictModal');if(modal)modal.hidden=true;if(!st.cloud)await loadCloud();const ok=await upload(true,{preserveLocalOnConflict:true,silent:false});if(ok)toast('Đã ghi bản local lên Cloud trong chế độ recovery.');return ok}
async function hydrate(){if(!st.session)return false;if(navigator.onLine===false){status('offline');return false}if(!appReady()){st.pendingSync=st.pendingSync||hasPersistentPending();status('syncing');return false}if(st.hydratePromise)return st.hydratePromise;st.hydratePromise=(async()=>{status('syncing');try{await loadProfile();await loadCloud();const persistent=hasPersistentPending();if(!st.cloud){const created=await upload(true,{preserveLocalOnConflict:true,clearPersistentPending:persistent,silent:true});if(!created){st.pendingSync=true;return false}status('online');return true}if(persistent){const pushed=await upload(false,{preserveLocalOnConflict:true,clearPersistentPending:true,silent:true});if(!pushed){st.pendingSync=true;status(navigator.onLine===false?'offline':'deferred');return false}status('online');return true}const applied=await applyCloud({silent:true});if(!applied)throw new Error('Cloud Save không thể áp dụng an toàn.');st.pendingSync=false;status('online');return true}catch(e){console.error(e);status(navigator.onLine===false?'offline':'error');if(navigator.onLine!==false)toast('Không thể kết nối hoặc áp dụng Cloud Save an toàn.');return false}finally{st.hydratePromise=null}})();return st.hydratePromise}
function schedule(reason='save'){if(!st.session||st.apply)return;st.pendingSync=true;clearTimeout(st.timer);if(navigator.onLine===false){status('offline');return}st.timer=setTimeout(()=>upload(false,{preserveLocalOnConflict:hasPersistentPending(),clearPersistentPending:hasPersistentPending(),silent:true}),Math.max(1500,Number(CFG().syncDebounceMs)||4000))}
'''
s = replace_range(s, 'async function applyCloud()', 'function authMsg(', lifecycle, 'online hydrate lifecycle')
old_sync = "$('#onlineSyncBtn')?.addEventListener('click',async()=>{await loadCloud();if(conflict())showConflict();else{await upload(false);toast('Đã đồng bộ.')}});"
new_sync = "$('#onlineSyncBtn')?.addEventListener('click',async()=>{const persistent=hasPersistentPending();if(st.pendingSync||persistent){const okSync=await upload(false,{preserveLocalOnConflict:persistent,clearPersistentPending:persistent});if(okSync)toast('Đã đồng bộ.');return}await loadCloud();const okApply=await applyCloud();if(okApply)toast('Cloud canonical đã được áp dụng.');});"
s = replace_once(s, old_sync, new_sync, 'online manual sync')
old_bind = "$('#onlineConflictUseCloud')?.addEventListener('click',applyCloud);$('#onlineConflictUseLocal')?.addEventListener('click',keepLocal);window.addEventListener('powder:local-save',e=>schedule(e.detail?.reason));"
new_bind = "$('#onlineConflictUseCloud')?.addEventListener('click',recoverUseCloud);$('#onlineConflictUseLocal')?.addEventListener('click',recoverUseLocal);window.addEventListener('powder:local-save',e=>schedule(e.detail?.reason));window.addEventListener('powder:app-booted',()=>{if(st.session&&navigator.onLine!==false)setTimeout(()=>hydrate(),0)},{passive:true});"
s = replace_once(s, old_bind, new_bind, 'online bind recovery')
old_api = "window.POWDER_ONLINE_V150={sync:()=>upload(false),open:openAuth,token:()=>token(),request:(path,opt={})=>authFetch(path,opt),reloadCloud:()=>loadCloud(),applyCloud:()=>applyCloud(),hydrate:()=>hydrate(),hasSession:()=>!!st.session,session:()=>st.session,state:()=>({configured:configured(),status:st.status,profile:st.profile,revision:st.revision,device:device(),session:!!st.session,online:navigator.onLine!==false,tabId:TAB_ID,multiTabSkips:st.multiTabSkips,remoteSyncs:st.remoteSyncs})};"
new_api = "window.POWDER_ONLINE_V150={sync:()=>upload(false,{preserveLocalOnConflict:hasPersistentPending(),clearPersistentPending:hasPersistentPending()}),open:openAuth,token:()=>token(),request:(path,opt={})=>authFetch(path,opt),reloadCloud:()=>loadCloud(),applyCloud:()=>applyCloud(),hydrate:()=>hydrate(),hasSession:()=>!!st.session,session:()=>st.session,canonicalFingerprint:value=>fingerprint(value),equivalent:(a,b)=>equivalent(a,b),openConflictRecovery:()=>showConflict(),state:()=>({configured:configured(),status:st.status,profile:st.profile,revision:st.revision,device:device(),session:!!st.session,online:navigator.onLine!==false,pendingSync:st.pendingSync||hasPersistentPending(),tabId:TAB_ID,multiTabSkips:st.multiTabSkips,remoteSyncs:st.remoteSyncs})};"
