# Replace Final Result verifier with the new locked UX/lifecycle contract.
verifier = r'''import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import vm from 'node:vm';
const root=process.cwd(),entry=fs.readFileSync(path.join(root,'js/combat-entry-v177.js'),'utf8'),controller=fs.readFileSync(path.join(root,'js/combat-result-controller-v1.js'),'utf8'),html=fs.readFileSync(path.join(root,'combat2.html'),'utf8');const checks=[];const check=(name,fn)=>{fn();checks.push(name)};
check('victory one confirm button source',()=>{assert.match(controller,/XÁC NHẬN & VỀ PHIÊU LƯU/);assert.doesNotMatch(controller,/TIẾP TỤC MÀN TIẾP THEO|TIẾP TỤC MÀN \$\{/)});
check('no nextReadiness',()=>assert.doesNotMatch(controller,/function nextReadiness/));
check('no next-stage progression lookup in result',()=>assert.doesNotMatch(controller,/progression\?\.nextStageId/));
check('settlement order',()=>{const a=controller.indexOf('academic.applyOfflineCombatAcademicOutcome({'),b=controller.indexOf('player.applyOfflineBattleReward({'),c=controller.indexOf('progress.applyOfflineAdventureVictory({'),d=controller.indexOf('saveReceipt(receipt)');assert.ok(a>=0&&a<b&&b<c&&c<d)});
check('receipt acknowledgement fields',()=>{assert.match(controller,/acknowledged:false,acknowledgedAt:null/);assert.match(controller,/acknowledged:true,acknowledgedAt:Date\.now\(\)/)});
check('ack before clear',()=>{const f=controller.slice(controller.indexOf('async function returnAfterSettlement'),controller.indexOf('async function confirmVictory'));assert.ok(f.indexOf('acknowledge()')<f.indexOf('clearBattleTransient()'))});
check('failure holds result',()=>{assert.match(controller,/Không thể xác nhận phần thưởng lúc này\.\\nKết quả trận đấu đã được giữ lại\./);assert.match(controller,/failed_retryable/)});
check('defeat retry return labels',()=>{assert.match(controller,/THỬ LẠI/);assert.match(controller,/VỀ PHIÊU LƯU/)});
check('defeat receipt has no reward progression',()=>assert.match(controller,/rewardGranted:\{coins:0,exp:0,wins:0\},progressionApplied:false/));
check('retry fresh identity',()=>{assert.match(controller,/Math\.max\(Date\.now\(\),Number\(request\.createdAt\|\|0\)\+1\)/);assert.match(controller,/next\.value\.battleId===request\.battleId/)});
check('normal PVE offline default',()=>{assert.match(entry,/function verifiedPveServerAuthority/);assert.match(entry,/return verified\?'server':'offline'/);const body=entry.slice(entry.indexOf('function runtimePveAuthorityMode'),entry.indexOf('function playerTeam'));assert.doesNotMatch(body,/hasSession|hasAccount/)});
check('main final ack reconcile only',()=>{assert.match(entry,/finalReceipt\.acknowledged===true/);assert.match(entry,/pendingAcknowledgement:true/);assert.match(entry,/clearPveTransient\(result\.value\.battleId\)/)});
check('legacy PVE authority guard explicit',()=>{const body=entry.slice(entry.indexOf('async function settleReturnedResult'),entry.indexOf('function scheduleSettlement'));assert.match(body,/\['server','online'\]\.includes\(String\(request\.value\.sourceContext\?\.authorityMode/)});
check('combat2 stays lightweight',()=>assert.doesNotMatch(html,/<script[^>]+app\.js/i));
check('controller cloud sync durable marker',()=>assert.match(controller,/powder_online_pending_sync_v150/));
check('controller requires active request result',()=>assert.match(controller,/if\(!req\?\.ok\|\|!battle\?\.ok/));
check('acknowledged controller never renders',()=>assert.match(controller,/if\(receipt\?\.acknowledged===true\)\{clearBattleTransient\(\);goAdventure\(\);return true\}/));
console.log('verify-combat-result-final-flow-v1: PASS',checks.length,'checks');
'''
Path('tools/verify-combat-result-final-flow-v1.mjs').write_text(verifier, encoding='utf-8')

cloud_verifier = r'''import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import assert from 'node:assert/strict';
const root=process.cwd(),source=fs.readFileSync(path.join(root,'js/online-foundation-v150.js'),'utf8'),entry=fs.readFileSync(path.join(root,'js/combat-entry-v177.js'),'utf8'),controller=fs.readFileSync(path.join(root,'js/combat-result-controller-v1.js'),'utf8');const checks=[];const check=(name,fn)=>{fn();checks.push(name)};
class Storage{constructor(){this.m=new Map()}getItem(k){return this.m.has(k)?this.m.get(k):null}setItem(k,v){this.m.set(k,String(v))}removeItem(k){this.m.delete(k)}}
const storage=new Storage(),listeners={};const document={readyState:'loading',addEventListener:(n,fn)=>{listeners[n]=fn},querySelector:()=>null,querySelectorAll:()=>[],body:{appendChild(){}}};const window={POWDER_ONLINE_CONFIG:{enabled:false},POWDER_CONFIG:{appVersion:'test'},localStorage:storage,document,addEventListener(){},dispatchEvent(){},crypto:{randomUUID:()=> 'uuid'}};window.window=window;const context={window,document,localStorage:storage,navigator:{onLine:true},crypto:window.crypto,console,setTimeout:()=>0,clearTimeout(){},fetch:async()=>{throw Error('unused')},BroadcastChannel:undefined,CustomEvent:class{},URL,URLSearchParams,history:{replaceState(){}},location:{hash:'',pathname:'/',search:'',protocol:'https:',origin:'https://test.invalid'}};vm.runInNewContext(source,context,{filename:'online-foundation-v150.js'});const api=window.POWDER_ONLINE_V150;assert.ok(api);
const save={saveVersion:15,rank:2,rankExp:7,exp:100,coins:500,knowledge:8,powCandy:2,powCandies:{common:2,rare:1,legendary:0},owned:{b:{level:3,stars:2,powExp:4,shards:5,shiny:false},a:{level:2,stars:1,powExp:1,shards:0,shiny:true}},team:['b','a'],favorites:['b','a'],lockedPows:['a'],lessonsDone:['l2','l1'],inventory:{z:1,a:2},adventure:{currentStage:3,stageStars:{'1-1':3}},bosses:{daily:{completed:true}},saveMeta:{schema:15,lastSavedAt:100,lastReason:'a',lastBattleRewardTx:{battleId:'c2-x',transactionId:'tx1'}}};
check('timestamp difference equivalent',()=>{const other=structuredClone(save);other.saveMeta.lastSavedAt=999;other.saveMeta.lastReason='different';assert.equal(api.equivalent(save,other),true)});
check('object order equivalent',()=>{const other={...structuredClone(save),owned:{a:save.owned.a,b:save.owned.b},inventory:{a:2,z:1}};assert.equal(api.equivalent(save,other),true)});
check('set-like ordering equivalent',()=>{const other=structuredClone(save);other.lessonsDone.reverse();other.favorites.reverse();assert.equal(api.equivalent(save,other),true)});
check('team ordering remains gameplay semantic',()=>{const other=structuredClone(save);other.team.reverse();assert.equal(api.equivalent(save,other),false)});
check('actual gameplay difference detected',()=>{const other=structuredClone(save);other.coins++;assert.equal(api.equivalent(save,other),false)});
check('owned pow detail detected',()=>{const other=structuredClone(save);other.owned.a.shards++;assert.equal(api.equivalent(save,other),false)});
check('world equipment artifact difference detected',()=>{const a={main:save,world:{equipmentOwned:{e1:1},artifactInstances:{x:{level:1}}}},b=structuredClone(a);b.world.artifactInstances.x.level=2;assert.equal(api.equivalent(a,b),false)});
check('transient UI excluded',()=>{const a=structuredClone(save),b=structuredClone(save);a.ui={tab:'a'};b.ui={tab:'b'};a.selectedStage='1-1';b.selectedStage='9-9';assert.equal(api.equivalent(a,b),true)});
check('dedupe identity retained',()=>{const other=structuredClone(save);other.saveMeta.lastBattleRewardTx.transactionId='tx2';assert.equal(api.equivalent(save,other),false)});
check('normal hydrate has no conflict modal',()=>{const body=source.slice(source.indexOf('async function hydrate()'),source.indexOf('function schedule('));assert.doesNotMatch(body,/showConflict\(/);assert.match(body,/applyCloud\(\{silent:true\}\)/)});
check('normal upload conflict auto cloud except protected pending',()=>{const body=source.slice(source.indexOf('async function upload('),source.indexOf('async function applyCloud('));assert.match(body,/preserveLocalOnConflict/);assert.match(body,/return await applyCloud\(\{silent:true\}\)/)});
check('cloud apply requires app authority',()=>{assert.match(source,/function appReady\(\).*applyCloudBundle/);assert.match(source,/if\(!st\.cloud\?\.save_data\|\|!appReady\(\)\)return false/)});
check('persistent combat sync marker shared',()=>{assert.match(source,/powder_online_pending_sync_v150/);assert.match(controller,/powder_online_pending_sync_v150/)});
check('pending conflict preserves local',()=>{const body=source.slice(source.indexOf('async function upload('),source.indexOf('async function applyCloud('));assert.match(body,/if\(preserveLocal\)\{st\.pendingSync=true;status\('deferred'\);return false\}/)});
check('normal flow no keepLocal',()=>assert.doesNotMatch(source,/function keepLocal\(/));
check('recovery choices explicit',()=>{assert.match(source,/function recoverUseCloud/);assert.match(source,/function recoverUseLocal/)});
check('state exposes pending sync',()=>assert.match(source,/pendingSync:st\.pendingSync\|\|hasPersistentPending\(\)/));
check('PVE login not server classification',()=>{const body=entry.slice(entry.indexOf('function runtimePveAuthorityMode'),entry.indexOf('function playerTeam'));assert.doesNotMatch(body,/hasSession|hasAccount/)});
console.log('verify-combat-result-cloud-lifecycle-v1: PASS',checks.length,'checks');
'''
Path('tools/verify-combat-result-cloud-lifecycle-v1.mjs').write_text(cloud_verifier, encoding='utf-8')
